function reviewed_migration(array $entry,string $candidate):bool {
 $pins=reviewed_migration_pins();$pin=$pins[$entry['version']??'']??null;
 if(!$pin||($entry['kind']??'')!=='reviewed_additive'||($entry['automatic']??false)!==true||($entry['required']??false)!==true)return false;
 foreach($pin as $key=>$value)if(($entry[$key]??null)!==$value)return false;
 if(hash_file('sha256',$candidate.'/'.$pin['operator'])!==$pin['operator_sha256'])return false;
 $sql=preg_replace('/^--[^\n]*$/m','',(string)file_get_contents($candidate.'/database/migrations/'.$entry['version'].'/up.sql'));
 $alters=['ALTER TABLE nd_deals ADD due_on DATE NULL, ADD loss_reason VARCHAR(500) NULL','ALTER TABLE nd_orders ADD due_on DATE NULL, ADD notes TEXT NULL','ALTER TABLE nd_employees ADD position VARCHAR(190) NULL'];
 foreach(array_filter(array_map('trim',explode(';',$sql))) as $s){if(preg_match('/^CREATE TABLE nd_[a-z_]+\s*\([\s\S]+\)\s*ENGINE=InnoDB[\s\S]*$/D',$s)===1)continue;if($entry['version']==='006_crm_operations'&&in_array($s,$alters,true))continue;return false;}return true;
}
function reviewed_recovery_proof(string $folder):void {
 $proof=read_json($folder.'/verified.json');
 insist(($proof['verified']??false)===true&&($proof['shadow_tables_removed']??false)===true&&($proof['source_data_written']??true)===false,'database_recovery_not_verified');
 insist(hash_file_safe($folder.'/rows.jsonl')===($proof['backup_sha256']??null)&&hash_file_safe($folder.'/schema.json')===($proof['schema_sha256']??null),'verified_database_backup_corrupt');
}
